    expect(addCosts(a, b)).toEqual({ baseInputUsd: 1.5, cacheReadUsd: 2.5, cacheWrite5mUsd: 3.5, cacheWrite1hUsd: 4.5, outputUsd: 5.5, totalUsd: 17.5 })
